  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["SW6", "R34", "R35"],
      "pins": ["SW6.3", "SW6.4", "SW6.1", "SW6.2", "R34.1", "R34.2", "R35.1", "R35.2"],
      "nets": ["/CAN0_P", "/CAN1_P", "/CAN0_N", "/CAN1_N", "Net-(R34-Pad2)", "Net-(R35-Pad2)"],
      "observed": "SW6's second pole connects /CAN1_P to /CAN0_P when closed. Its first pole connects /CAN0_N and /CAN1_N through R34 and R35, each 120 ohms, when closed.",
      "expected": "CAN0 and CAN1 should remain separate buses, consistent with the specification's description of two isolated CAN buses. A switchable link should not directly join one pair of CAN signals while linking the other pair through two series resistors.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "/CAN0_P : ... SW6.4(passive) ..."
        },
        {
          "source": "netlist",
          "quote": "/CAN1_P : ... SW6.3(passive) ..."
        },
        {
          "source": "netlist",
          "quote": "Net-(R34-Pad2) : R34.2(2,passive) SW6.1(passive)"
        },
        {
          "source": "netlist",
          "quote": "Net-(R35-Pad2) : R35.2(2,passive) SW6.2(passive)"
        },
        {
          "source": "netlist",
          "quote": "R34 | 120R"
        },
        {
          "source": "netlist",
          "quote": "R35 | 120R"
        },
        {
          "source": "spec",
          "quote": "two isolated CAN buses (CAN0, CAN1), each driven by its own MCP2515 SPI CAN controller"
        }
      ],
      "impact": "Closing the relevant DIP switch poles couples the two CAN interfaces; directly tying their positive lines can cause bus contention or disrupt communication, and the negative-line connection is not a conventional CAN termination.",
      "confidence": 0.84
    }
  ],
  "summary": "The design contains a switchable coupling between CAN0 and CAN1 that conflicts with their specified role as separate isolated buses. The coupling is conditional on SW6 being closed."
}

